def count_primes(n):
    """Counts the number of primes less than or equal to n (pi(n))."""
    if n < 2:
        return 0
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    count = 0
    for i in range(2, n + 1):
        if is_prime[i]:
            count += 1
    return count

def calculate_k(n):
    """Calculates omega(n!/2023) based on the derived formula."""
    pi_n = count_primes(n)

    # Contribution from primes p not equal to 7 or 17
    count_other_primes = pi_n
    if n >= 7:
        count_other_primes -= 1  # Exclude 7
    if n >= 17:
        count_other_primes -= 1  # Exclude 17

    # Contribution from p=7: v_7(n!) > v_7(2023) = 1. Requires n >= 14.
    contribution_7 = 1 if n >= 14 else 0

    # Contribution from p=17: v_17(n!) > v_17(2023) = 2. Requires n >= 51.
    contribution_17 = 1 if n >= 51 else 0

    k = count_other_primes + contribution_7 + contribution_17
    return k

# Test values around the estimated bound (n=40) and the suspected upper bound (n=50)
test_values = [36, 37, 40, 41, 50, 51]
results = {}
for n in test_values:
    k_n = calculate_k(n)
    results[n] = k_n

print("Results for k(n) = omega(n!/2023):")
for n, k in results.items():
