def prime_count(n):
    """Calculates pi(n), the number of primes less than or equal to n."""
    primes = []
    is_prime = [True] * (n + 1)
    if n >= 0:
        is_prime[0] = False
    if n >= 1:
        is_prime[1] = False

    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    return len(primes)

# We established that for n >= 34, 17 is not a prime factor of K = n!/2023, 
# since v_17(n!) <= 2 for n <= 45, but we need v_17(n!) >= 3.
# Also, 7 is always a prime factor for n >= 30.
# Thus, omega(K) = pi(n) - 1.

